/bin/bash -lc "cd [workspace path] && python -c \"
import numpy as np
from scipy import ndimage
d = np.load('source_pixels.npz')['rgb']
for t in range(0,96,2):
    f=d[t].astype(int)
    mask = (f[:,:,0] > f[:,:,1]+25) & (f[:,:,0] > f[:,:,2]+25)
    lab,n = ndimage.label(mask)
    sizes = ndimage.sum(mask, lab, range(1,n+1))
    # candidate ball: component size 30-400, above y60
    best=None
    for cid in range(1,n+1):
        s=sizes[cid-1]
        if 30<=s<=400:
            ys,xs=np.nonzero(lab==cid)
            if ys.max()<62:
                if best is None or s>best[0]: best=(s,xs.mean(),ys.mean(),xs.min(),xs.max(),ys.min(),ys.max())
    if best: print(t, 'size',int(best[0]),'cx',round(best[1],1),'cy',round(best[2],1),'bbox',best[3:])
    else: print(t,'no ball above ground')
\""
